#!/usr/bin/env python3
import os
import json

output_files = {
    'T01 Selected Indicators': 'outputs/t01_selected_indicators.csv',
    'T05 Clean Stops': 'outputs/t05_clean_stops.csv',
    'T08 POIs Clean': 'outputs/t08_pois_clean.csv',
    'T10 Accessibility Scores': 'outputs/t10_accessibility_scores.csv',
    'T13 City Clusters': 'outputs/t13_city_clusters.csv'
}

validation_summary = []

for check_name, file_path in output_files.items():
    check_passed = True
    message = 'Check passed'
    if not os.path.exists(file_path):
        check_passed = False
        message = f'{file_path} is missing.'
    elif os.path.getsize(file_path) == 0:
        check_passed = False
        message = f'{file_path} is empty.'
    validation_summary.append({
        'check_name': check_name,
        'passed': check_passed,
        'message': message
    })

with open('outputs/t14_validation_summary.json', 'w') as f:
    json.dump(validation_summary, f, indent=4)

if __name__ == '__main__':
    pass  # The script does not need to do anything if executed directly

